#!/usr/bin/env python3
from pathlib import Path
import json
html=r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Research evidence on salmon farming, at a glance</title><script src="https://cdn.jsdelivr.net/npm/d3@7"></script><script src="https://cdn.jsdelivr.net/npm/topojson-client@3"></script><style>:root{--ink:#2c454a;--mid:#577c84;--pale:#a8bdbe;--sand:#e2b8a2;--coral:#ff9d78;--red:#e55634;--paper:#f7f7f3;--line:#d9e2e1}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:15px/1.45 Inter,system-ui,sans-serif}header{padding:34px 5vw 28px;background:var(--ink);color:#fff}h1{font-size:clamp(30px,4vw,52px);line-height:1.04;margin:7px 0 9px}header p{max-width:900px;margin:0;color:#dce7e7}.wrap{width:min(1450px,92vw);margin:auto}.kpis{display:grid;grid-template-columns:repeat(6,1fr);gap:12px;margin:-22px auto 26px;position:relative}.kpi,.section{background:#fff;border:1px solid var(--line);border-radius:13px;box-shadow:0 6px 20px #2c454a12}.kpi{padding:16px}.kpi b{font-size:25px}.kpi small{display:block;text-transform:uppercase;letter-spacing:.08em;color:var(--mid);margin-top:4px}.section{padding:22px;margin:18px 0}.section h2{margin:0 0 4px}.sub{color:var(--mid);margin:0 0 16px}.controls{display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin-bottom:15px}select,input,button{font:inherit;border:1px solid #cbd8d7;border-radius:8px;background:#fff;color:var(--ink);padding:9px 11px}button{cursor:pointer}.chart{min-height:420px}.map{min-height:520px}.table-wrap{overflow:auto;border:1px solid var(--line);border-radius:8px}.table{width:100%;border-collapse:collapse;min-width:1000px}.table th{position:sticky;top:0;background:#eef3f2;text-align:left;font-size:11px;text-transform:uppercase;padding:10px}.table td{padding:9px;border-top:1px solid #e8eeee;vertical-align:top}.pill{display:inline-block;background:#eaf0ef;border-radius:99px;padding:3px 7px;margin:2px;font-size:11px}.muted{color:var(--mid);font-size:12px}.pager{display:flex;justify-content:flex-end;gap:8px;align-items:center;margin-top:12px}.tree ul{list-style:none;margin:0;padding-left:22px}.tree li{margin:4px 0}.tree button{border:0;background:none;padding:2px;text-align:left;color:var(--ink)}.nodecount{color:var(--mid);font-size:12px;margin-left:5px}.axis text{font-size:11px;fill:var(--mid)}.heat-cell{stroke:#fff}.tooltip{position:fixed;display:none;pointer-events:none;background:var(--ink);color:white;padding:8px 10px;border-radius:6px;font-size:12px;z-index:9}@media(max-width:1000px){.kpis{grid-template-columns:repeat(3,1fr)}}@media(max-width:600px){.kpis{grid-template-columns:1fr 1fr}.section{padding:15px}}</style></head><body><header><div class="wrap"><div>Living Evidence Map</div><h1>Research evidence on salmon farming, at a glance</h1><p>An interactive view of the living evidence map. The map is updated automatically, with human oversight on a weekly basis. Data are sourced from <a href="https://www.lens.org" style="color:#fff">www.lens.org</a>.</p></div></header><main class="wrap"><div id="kpis" class="kpis"></div><section class="section"><h2>Geographic distribution</h2><p class="sub">Click a country to filter the database. The species filter is applied at the same time.</p><div class="controls"><label>Species <select id="mapSpecies"><option value="__all__">All species</option></select></label></div><div id="map" class="map"></div></section><section class="section"><h2>Evidence by species × topic</h2><p class="sub">Click a cell to filter the database. Topics are grouped by the evidence hierarchy.</p><div class="controls"><label>Species <select id="heatSpecies"><option value="__all__">All species</option></select></label><label>Top-level topic <select id="heatTop"><option value="__all__">All topics</option></select></label><label>Topic hierarchy <select id="heatLevel"></select></label><label>Show <select id="heatLimit"><option>20</option><option selected>35</option><option>60</option></select></label></div><div id="heatmap" class="chart"></div></section><section class="section"><h2>Topic hierarchy</h2><p class="sub">Expand a branch to explore finer topics. Click any node to filter the database to that branch.</p><div id="tree" class="tree"></div></section><section class="section" id="database"><h2>Master database</h2><p class="sub">Filters selected above are applied here.</p><div class="controls"><input id="q" placeholder="Search title, abstract or record ID…"><label>Species <select id="tableSpecies"><option value="__all__">All species</option></select></label><label>Country <select id="tableCountry"><option value="__all__">All countries</option></select></label><input id="topicFilter" readonly placeholder="Topic filter: none" style="min-width:280px"><button id="clear">Clear filters</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Record</th><th>Title</th><th>Year</th><th>Species</th><th>Country</th><th>Topics</th></tr></thead><tbody id="tbody"></tbody></table></div><div class="pager"><button id="prev">Previous</button><span id="page"></span><button id="next">Next</button></div></section></main><div id="tip" class="tooltip"></div><script>
const pal=['#2c454a','#577c84','#a8bdbe','#e2b8a2','#ff9d78','#e55634'],fmt=d3.format(','),esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));let D,state={species:'__all__',country:'__all__',topic:null,q:'',page:1,size:50};
const jump=()=>document.getElementById('database').scrollIntoView({behavior:'smooth',block:'start'});function setFilter(x){Object.assign(state,x);state.page=1;document.getElementById('tableSpecies').value=state.species;document.getElementById('tableCountry').value=state.country;document.getElementById('q').value=state.q;document.getElementById('topicFilter').value=state.topic?'Topic filter: '+state.topic:'Topic filter: none';table();jump()}
function recordsFor(r){return D.records.filter(x=>(state.species==='__all__'||x.species.includes(state.species))&&(state.country==='__all__'||x.iso3.includes(state.country))&&(!state.topic||x.topics.includes(state.topic)||Object.values(x).filter(v=>Array.isArray(v)).flat().includes(state.topic))&&(!state.q||[x.record_id,x.title,x.abstract,x.year,...x.species,...x.countries,...x.topics].join(' ').toLowerCase().includes(state.q.toLowerCase())))}
function table(){const a=recordsFor(),pages=Math.max(1,Math.ceil(a.length/state.size));state.page=Math.min(state.page,pages);const z=a.slice((state.page-1)*state.size,state.page*state.size);tbody.innerHTML=z.map(r=>`<tr><td class="muted">${esc(r.record_id)}</td><td><b>${esc(r.title||'Untitled')}</b><div class="muted">${esc((r.abstract||'').slice(0,180))}</div></td><td>${esc(r.year)}</td><td>${r.species.filter(s=>s!=='Unspecified species').map(s=>`<span class="pill">${esc(s)}</span>`).join('')}</td><td>${esc(r.countries.join('; '))}</td><td>${r.topics.map(t=>`<span class="pill">${esc(t)}</span>`).join('')}</td></tr>`).join('');page.textContent=`${state.page} / ${pages} · ${fmt(a.length)} matching`;prev.disabled=state.page<=1;next.disabled=state.page>=pages}
function map(){const el=d3.select('#map');el.selectAll('*').remove();const sp=state.species,vals=sp==='__all__'?D.country_iso3_counts:(D.country_iso3_species_counts?.[sp]||{}),w=el.node().clientWidth||900,h=500,svg=el.append('svg').attr('width','100%').attr('viewBox',`0 0 ${w} ${h}`),path=d3.geoPath(d3.geoNaturalEarth1().fitSize([w,h],{type:'Sphere'})),max=d3.max(Object.values(vals))||1,color=d3.scaleSequential(d3.interpolateRgbBasis([pal[2],pal[1],pal[0],pal[5]])).domain([0,max]);d3.json('https://cdn.jsdelivr.net/npm/world-atlas@2/countries-110m.json').then(world=>svg.selectAll('path').data(topojson.feature(world,world.objects.countries).features).join('path').attr('d',path).attr('fill',d=>color(vals[String(d.id)]||0)).attr('stroke','#fff').on('mousemove',(e,d)=>{const n=vals[String(d.id)]||0;tip(e,`<b>${esc(d.properties.name)}</b><br>${fmt(n)} records`)}).on('mouseleave',hide).on('click',(e,d)=>{if(vals[String(d.id)])setFilter({species:state.species,country:countryForMap(d.id),topic:null})}));}
function countryForMap(id){const rev=D.iso3_to_iso3||{};return Object.entries(rev).find(([a,b])=>String(b)===String(id))?.[0]||String(id)}function tip(e,s){const t=document.getElementById('tip');t.innerHTML=s;t.style.display='block';t.style.left=e.clientX+12+'px';t.style.top=e.clientY+12+'px'}function hide(){tip.style.display='none'}
function heat(){const el=d3.select('#heatmap');el.selectAll('*').remove();const lev=heatLevel.value,top=heatTop.value,sp=heatSpecies.value,limit=+heatLimit.value;let topics=Object.entries(D.topic_level_counts[lev]||{}).sort((a,b)=>b[1]-a[1]).map(x=>x[0]);if(top!=='__all__'){const descendants=[];const walk=(obj,on)=>Object.entries(obj||{}).forEach(([k,n])=>{if(on||k===top){descendants.push(k);walk(n.children,true)}else walk(n.children,false)});walk(D.topic_tree,false);topics=topics.filter(x=>descendants.includes(x))}topics=topics.slice(0,limit);let ss=Object.keys(D.species_counts);if(sp!=='__all__')ss=[sp];const w=Math.max(el.node().clientWidth,900),cw=Math.max(28,(w-190)/Math.max(1,topics.length)),ch=34,left=180,bottom=145,h=35+ss.length*ch+bottom,svg=el.append('svg').attr('width','100%').attr('viewBox',`0 0 ${Math.max(w,left+topics.length*cw)} ${h}`),counts=D.species_topic_level_counts[lev]||{},max=d3.max(ss.flatMap(s=>topics.map(t=>counts[`${s}|||${t}`]||0)))||1,color=d3.scaleSequential(d3.interpolateRgbBasis([pal[2],pal[1],pal[0],pal[5]])).domain([0,max]);svg.selectAll('.row').data(ss).join('g').attr('transform',(s,i)=>`translate(${left},${35+i*ch})`).each(function(s){d3.select(this).selectAll('rect').data(topics).join('rect').attr('x',t=>topics.indexOf(t)*cw).attr('width',cw).attr('height',ch).attr('fill',t=>color(counts[`${s}|||${t}`]||0)).attr('class','heat-cell').on('click',()=>setFilter({species:s,topic:topics[topics.indexOf(t)]})).on('mousemove',(e,t)=>tip(e,`<b>${esc(s)}</b><br>${esc(t)}<br>${fmt(counts[`${s}|||${t}`]||0)} records`)).on('mouseleave',hide)});svg.append('g').selectAll('text').data(ss).join('text').attr('x',left-8).attr('y',(s,i)=>35+i*ch+22).attr('text-anchor','end').attr('class','axis').text(s=>s);svg.append('g').selectAll('text').data(topics).join('text').attr('transform',(t,i)=>`translate(${left+i*cw+cw/2},${35+ss.length*ch+18}) rotate(-55)`).attr('text-anchor','end').attr('class','axis').text(t=>t);}
function tree(){const root=document.getElementById('tree');root.innerHTML='';function branch(obj,parent){const ul=document.createElement('ul');Object.entries(obj).sort((a,b)=>b[1].count-a[1].count).forEach(([name,n])=>{const li=document.createElement('li');const b=document.createElement('button');b.textContent=(Object.keys(n.children).length?'▸ ':'')+name+' ';const c=document.createElement('span');c.className='nodecount';c.textContent=fmt(n.count);b.appendChild(c);b.onclick=()=>setFilter({topic:name});li.appendChild(b);if(Object.keys(n.children).length){const sub=branch(n.children,li);sub.style.display='none';b.onclick=()=>{sub.style.display=sub.style.display==='none'?'block':'none';setFilter({topic:name})};li.appendChild(sub)}ul.appendChild(li)});return ul}root.appendChild(branch(D.topic_tree,root))}
async function start(){D=await fetch('dashboard.json?'+Date.now()).then(r=>r.json());const sp=Object.keys(D.species_counts);[...sp].forEach(s=>{mapSpecies.add(new Option(s,s));heatSpecies.add(new Option(s,s));tableSpecies.add(new Option(s,s))});const countries=Object.keys(D.country_iso3_counts||{});countries.forEach(c=>tableCountry.add(new Option(c,c)));Object.entries(D.topic_level_labels).forEach(([k,v])=>heatLevel.add(new Option(v,k)));Object.keys(D.topic_tree).forEach(t=>heatTop.add(new Option(t,t)));kpis.innerHTML=[['Last update','13/08/2026'],['Records',D.metrics.total_records],['Countries',D.metrics.total_countries],['Species',D.metrics.total_species],['Topics',D.metrics.total_topics],['Search results screened',D.metrics.candidate_search_results_screened??'—']].map(x=>`<div class="kpi"><b>${esc(x[1])}</b><small>${esc(x[0])}</small></div>`).join('');mapSpecies.onchange=()=>{state.species=mapSpecies.value;map()};heatSpecies.onchange=()=>{heat();};heatTop.onchange=heat;heatLevel.onchange=heat;heatLimit.onchange=heat;tableSpecies.onchange=()=>setFilter({species:tableSpecies.value});tableCountry.onchange=()=>setFilter({country:tableCountry.value});q.oninput=()=>setFilter({q:q.value});clear.onclick=()=>setFilter({species:'__all__',country:'__all__',topic:null,q:''});prev.onclick=()=>{state.page--;table()};next.onclick=()=>{state.page++;table()};heat();tree();table();map()}start();</script></body></html>'''
Path('docs/index.html').write_text(html,encoding='utf-8')
print('Built interactive dashboard HTML')
